import{_ as l,l as d,o as e,c as s,v as r,p as n,x as o,d as i,i as c,S as p}from"./chunks/framework.InCnrqk-.js";const b=JSON.parse('{"title":"语言内存模型与 data race","description":"","frontmatter":{"title":"语言内存模型与 data race","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/language-memory-model.md","filePath":"cs/language-memory-model.md","lastUpdated":1789023840000}'),h={name:"cs/language-memory-model.md"};function m(u,a,C,_,f,B){const t=d("Mermaid");return e(),s("div",null,[a[1]||(a[1]=r('<h1 id="语言内存模型与-data-race" tabindex="-1">语言内存模型与 data race <a class="header-anchor" href="#语言内存模型与-data-race" aria-label="Permalink to &quot;语言内存模型与 data race&quot;">​</a></h1><div class="epigraph"><p>没有 data race 时，程序等价于某种交错的顺序一致执行。有 race 时，C/C++ 是未定义，Java 仍限制可见性。编译器重排必须遵守 happens-before。</p><footer>—— 据 Adve and Hill；Boehm and Adve, Foundations of the C++ Concurrency Memory Model；Java Memory Model（JSR-133）整理</footer></div><p>上一课<a href="/cs/reflection-metadata">反射</a> 可在运行时改字段，并发更乱。缺口是<strong>语言级内存模型</strong>：什么重排合法，data race 是不是 UB。接<a href="/cs/undefined-behavior-opt">UB 与优化</a> 与组成课一致性，但不重讲总线。WebAssembly 下一课当目标。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>优化想把 load 提出循环；另一线程在写。无模型则要么禁止优化要么允许乱看。JMM/C++11：原子与锁建立 happens-before。缺口是<strong>编译器合同</strong>，不是硬件 MESI 细节。</p><p>Data race：冲突访问、至少一个写、无排序。C++：UB。Java：不崩型，但值可撕（除 long/double 特殊）——仍几乎不可写。</p><h3 id="内存模型不是-gc-写屏障" tabindex="-1">内存模型不是 GC 写屏障 <a class="header-anchor" href="#内存模型不是-gc-写屏障" aria-label="Permalink to &quot;内存模型不是 GC 写屏障&quot;">​</a></h3><p>GC 屏障维持三色；内存模型屏障维持可见性。JIT 可能同一条 store 两件事，概念分开。</p><p><span class="marginnote">Boehm–Adve 2008。JSR-133。Adve–Gharachorloo 综述硬件。本课语言层。不写利用级竞态教程。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>IR：<code>atomic</code> 带序（relaxed/acquire/release/seqcst）。优化：不跨原子乱序普通访问。逃逸到多线程的对象：锁消除要证明无逃逸。</p>',11)),(e(),n(p,null,{default:o(()=>[c(t,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20RACE%5B%22data%20race%22%5D%20--%3E%20C%5B%22C%2B%2B%EF%BC%9AUB%22%5D%0A%20%20RACE%20--%3E%20J%5B%22Java%EF%BC%9A%E5%BC%B1%E4%BF%9D%E8%AF%81%22%5D%0A%20%20SYNC%5B%22%E9%94%81%20%2F%20%E5%8E%9F%E5%AD%90%22%5D%20--%3E%20HB%5B%22happens-before%22%5D%0A%20%20HB%20--%3E%20SC%5B%22DRF%20%E2%87%92%20SC%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[i(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<p>与 fast-math 无关；与并发 GC 的对象发布有关：必须安全发布。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>编译器+硬件共同实现模型。<code>volatile</code> 在 Java 与 C 意义不同——点名坑。不要用普通 load 当旗。</p><p>DRF-SC：无 race 则程序员可当顺序一致想。有 race 的 C++ 程序优化可删除看起来「有用」的代码。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写全部内存序表。后课默认：优化受内存模型约束。下一课 WebAssembly 作目标：另一 ABI+线性内存。</p><p>也不把模型当经济学博弈。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>DRF ⇒ 顺序一致交错；C++ race 是 UB。</li><li>原子序限制重排；与 GC 屏障不同。</li><li>锁消除、LICM 必须看逃逸与同步。</li><li>出处：Boehm and Adve；JSR-133；Adve and Hill。</li></ul>',9))])}const g=l(h,[["render",m]]);export{b as __pageData,g as default};
